@namespace sv_991b2b166c414704b26e29f9a38c7b67.Components.Settings

<nav class="nav flex-column settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="nav-link settings-nav-btn @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            @section
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_991b2b166c414704b26e29f9a38c7b67.Components.Settings
@using sv_991b2b166c414704b26e29f9a38c7b67.Services

<div class="profile-section">
    <h4 class="mb-4">Profile Settings</h4>

    <div class="d-flex align-items-center mb-4">
        <div class="avatar-preview me-4">
            <img src="@DisplayName" class="rounded-circle" width="80" height="80"
                 alt="Avatar" onerror="this.style.display='none'" />
            @* Show initials fallback *@
        </div>
        <div class="flex-grow-1">
            <label class="form-label text-muted small">Avatar URL</label>
            <input type="url" class="form-control" value="@AvatarUrl"
                   @oninput="e => AvatarUrl = e.Value?.ToString() ?? string.Empty" />
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Display Name</label>
        <input type="text" class="form-control" value="@DisplayNameField"
               @oninput="e => DisplayNameField = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <input type="email" class="form-control" value="@Email"
               @oninput="e => Email = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="mb-3">
        <label class="form-label">Bio</label>
        <textarea class="form-control" rows="4" @oninput="e => Bio = e.Value?.ToString() ?? string.Empty">@Bio</textarea>
    </div>

    @if (!string.IsNullOrEmpty(StatusMessage))
    {
        <div class="alert @(IsError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @StatusMessage
            <button type="button" class="btn-close" @onclick="() => StatusMessage = string.Empty"></button>
        </div>
    }

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @if (IsSaving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayNameField { get; set; } = "";
    private string Email { get; set; } = "";
    private string AvatarUrl { get; set; } = "";
    private string Bio { get; set; } = "";

    // Used for avatar preview src
    private string DisplayName => AvatarUrl;

    private string StatusMessage { get; set; } = "";
    private bool IsError { get; set; }
    private bool IsSaving { get; set; }

    protected override void OnParametersSet()
    {
        if (!IsSaving)
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        DisplayNameField = Profile.DisplayName;
        Email = Profile.Email;
        AvatarUrl = Profile.AvatarUrl;
        Bio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        IsError = false;
        StatusMessage = "";
        try
        {
            var updated = new UserProfile(DisplayNameField, Email, AvatarUrl, Bio);
            await OnSave.InvokeAsync(updated);
            StatusMessage = "Profile saved successfully!";
        }
        catch (Exception ex)
        {
            StatusMessage = $"Error saving profile: {ex.Message}";
            IsError = true;
        }
        finally
        {
            IsSaving = false;
        }
    }

    private void Discard()
    {
        LoadFromProfile();
        StatusMessage = "";
    }
}

@namespace sv_991b2b166c414704b26e29f9a38c7b67.Components.Settings
@using sv_991b2b166c414704b26e29f9a38c7b67.Services

<div class="notifications-section">
    <h4 class="mb-4">Notification Preferences</h4>

    <div class="card mb-3">
        <div class="card-body">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif"
                       checked="@EmailNotifications"
                       @onchange="e => EmailNotifications = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="emailNotif">
                    <strong>Email Notifications</strong>
                    <div class="text-muted small">Receive notifications via email</div>
                </label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif"
                       checked="@PushNotifications"
                       @onchange="e => PushNotifications = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="pushNotif">
                    <strong>Push Notifications</strong>
                    <div class="text-muted small">Receive push notifications in browser</div>
                </label>
            </div>

            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="weeklyDigest"
                       checked="@WeeklyDigest"
                       @onchange="e => WeeklyDigest = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="weeklyDigest">
                    <strong>Weekly Digest</strong>
                    <div class="text-muted small">Get a weekly summary of activity</div>
                </label>
            </div>
        </div>
    </div>

    <div class="card mb-4">
