<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @* Change Password Panel *@
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center"
             role="button" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen"
             style="cursor: pointer;">
            <strong>Change Password</strong>
            <span>@(PasswordPanelOpen ? "▲" : "▼")</span>
        </div>
        @if (PasswordPanelOpen)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="CurrentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="NewPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="ConfirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(PasswordMessage))
                {
                    <div class="alert @(PasswordIsError ? "alert-danger" : "alert-success") py-2" role="alert">
                        @PasswordMessage
                    </div>
                }

                <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@IsChangingPassword">
                    @if (IsChangingPassword)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Update Password
                </button>
            </div>
        }
    </div>

    @* Two-Factor Authentication *@
    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <strong>Two-Factor Authentication</strong>
                <div class="text-muted small mt-1">
                    Status:
                    @if (TwoFactorEnabled)
                    {
                        <span class="badge bg-success">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Disabled</span>
                    }
                </div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@TwoFactorEnabled"
                       @onchange="e => TwoFactorEnabled = (bool)(e.Value ?? false)" />
            </div>
        </div>
    </div>

    @* Last Password Change *@
    @if (Security.LastPasswordChange.HasValue)
    {
        <p class="text-muted small mb-4">
            Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
        </p>
    }

    @* Active Sessions *@
    <div class="card">
        <div class="card-header"><strong>Active Sessions</strong></div>
        <div class="card-body p-0">
            <div class="table-responsive">
                <table class="table table-hover mb-0">
                    <thead class="table-light">
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Security.Sessions)
                        {
                            var isCurrentSession = session.Id == CurrentSessionId;
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrentSession)
                                    {
                                        <span class="badge bg-primary ms-1">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (!isCurrentSession)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>
    </div>

    @* Revoke Confirmation Dialog *@
    @if (SessionToRevoke is not null)
    {
        <div class="modal-backdrop fade show"></div>
        <div class="modal d-block fade show" tabindex="-1" role="dialog">
            <div class="modal-dialog modal-dialog-centered" role="document">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Revoke Session</h5>
                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                    </div>
                    <div class="modal-body">
                        <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> from <strong>@SessionToRevoke.Location</strong>?</p>
                        <p class="text-muted small">This will sign out that device immediately.</p>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@IsRevoking">
                            @if (IsRevoking)
                            {
                                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            }
                            Revoke Session
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }

    // The first session is treated as the "current" session
    private string CurrentSessionId => Security.Sessions.Count > 0 ? Security.Sessions[0].Id : "";

    private bool PasswordPanelOpen { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string PasswordMessage { get; set; } = "";
    private bool PasswordIsError { get; set; }
    private bool IsChangingPassword { get; set; }

    private bool TwoFactorEnabled { get; set; }

    private ActiveSession? SessionToRevoke { get; set; }
    private bool IsRevoking { get; set; }

    protected override void OnParametersSet()
    {
        TwoFactorEnabled = Security.TwoFactorEnabled;
    }

    private async Task UpdatePasswordAsync()
    {
        PasswordMessage = "";
        PasswordIsError = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            PasswordMessage = "Current password is required.";
            PasswordIsError = true;
            return;
        }

        if (string.IsNullOrWhiteSpace(NewPassword) || NewPassword.Length < 8)
        {
            PasswordMessage = "New password must be at least 8 characters.";
            PasswordIsError = true;
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            PasswordMessage = "New password and confirmation do not match.";
            PasswordIsError = true;
            return;
        }

        IsChangingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            PasswordMessage = "Password updated successfully!";
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            PasswordMessage = $"Error: {ex.Message}";
            PasswordIsError = true;
        }
        finally
        {
            IsChangingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session) => SessionToRevoke = session;
    private void CancelRevoke() => SessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is null) return;
        IsRevoking = true;
        try
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
        finally
        {
            IsRevoking = false;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

