@using sv_991b2b166c414704b26e29f9a38c7b67.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    <div class="row">
        <div class="col-md-7">
            @* Theme *@
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>
            </div>

            @* Font Size *@
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Font Size</h6>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(FontSize == size)"
                                   @onchange="() => FontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>
            </div>

            @* Language *@
            <div class="card mb-3">
                <div class="card-body">
                    <h6 class="card-title">Language</h6>
                    <select class="form-select" value="@Language"
                            @onchange="e => Language = e.Value?.ToString() ?? "English"">
                        @foreach (var lang in Languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>
            </div>

            @* Compact Mode *@
            <div class="card mb-3">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-0">Compact Mode</h6>
                        <span class="text-muted small">Reduce spacing and padding throughout the UI</span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode"
                               checked="@CompactMode"
                               @onchange="e => CompactMode = (bool)(e.Value ?? false)" />
                    </div>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(StatusMessage))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @StatusMessage
                    <button type="button" class="btn-close" @onclick="() => StatusMessage = string.Empty"></button>
                </div>
            }

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @if (IsSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Save
            </button>
        </div>

        @* Live Preview *@
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><strong>Live Preview</strong></div>
                <div class="card-body preview-area @PreviewThemeClass" style="@PreviewStyle">
                    <h6 style="@PreviewFontStyle">Sample Heading</h6>
                    <p style="@PreviewFontStyle" class="@(CompactMode ? "mb-1" : "mb-3")">
                        This is a preview of how your content will look with the selected appearance settings.
                    </p>
                    <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-3")">
                        <span class="badge bg-primary">Badge</span>
                        <span class="badge bg-success">Active</span>
                    </div>
                    <button class="btn btn-sm btn-primary" style="@PreviewFontStyle" disabled>
                        Sample Button
                    </button>
                    <p class="text-muted mt-2 small" style="@PreviewFontStyle">
                        Language: @Language · Font: @FontSize · @(CompactMode ? "Compact" : "Standard") spacing
                    </p>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }

    private string StatusMessage { get; set; } = "";
    private bool IsSaving { get; set; }

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese", "Chinese"];

    protected override void OnParametersSet()
    {
        Theme = Settings.Theme;
        FontSize = Settings.FontSize;
        Language = Settings.Language;
        CompactMode = Settings.CompactMode;
    }

    private string PreviewThemeClass => Theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewStyle => Theme switch
    {
        "Dark" => "background-color: #1e1e1e; color: #e0e0e0; border-radius: 0.5rem;",
        _ => "background-color: #ffffff; color: #212529; border-radius: 0.5rem;"
    };

    private string PreviewFontStyle => FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private async Task SaveAsync()
    {
        IsSaving = true;
        StatusMessage = "";
        try
        {
            var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
            await OnSave.InvokeAsync(updated);
            StatusMessage = "Appearance saved successfully!";
        }
        finally
        {
            IsSaving = false;
        }
    }
}
