+            Save Changes
+        </button>
+        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
+    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }
+
+    private string DisplayNameField { get; set; } = "";
+    private string Email { get; set; } = "";
+    private string AvatarUrl { get; set; } = "";
+    private string Bio { get; set; } = "";
+
+    // Used for avatar preview src
+    private string DisplayName => AvatarUrl;
+
+    private string StatusMessage { get; set; } = "";
+    private bool IsError { get; set; }
+    private bool IsSaving { get; set; }
+
+    protected override void OnParametersSet()
+    {
+        if (!IsSaving)
+        {
+            LoadFromProfile();
+        }
+    }
+
+    private void LoadFromProfile()
+    {
+        DisplayNameField = Profile.DisplayName;
+        Email = Profile.Email;
+        AvatarUrl = Profile.AvatarUrl;
+        Bio = Profile.Bio;
+    }
+
+    private async Task SaveAsync()
+    {
+        IsSaving = true;
+        IsError = false;
+        StatusMessage = "";
+        try
+        {
+            var updated = new UserProfile(DisplayNameField, Email, AvatarUrl, Bio);
+            await OnSave.InvokeAsync(updated);
+            StatusMessage = "Profile saved successfully!";
+        }
+        catch (Exception ex)
+        {
+            StatusMessage = $"Error saving profile: {ex.Message}";
+            IsError = true;
+        }
+        finally
+        {
+            IsSaving = false;
+        }
+    }
+
+    private void Discard()
+    {
+        LoadFromProfile();
+        StatusMessage = "";
+    }
+}
