@namespace sv_991b2b166c414704b26e29f9a38c7b67.Components.Settings
@using sv_991b2b166c414704b26e29f9a38c7b67.Services

<div class="notifications-section">
    <h4 class="mb-4">Notification Preferences</h4>

    <div class="card mb-3">
        <div class="card-body">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif"
                       checked="@EmailNotifications"
                       @onchange="e => EmailNotifications = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="emailNotif">
                    <strong>Email Notifications</strong>
                    <div class="text-muted small">Receive notifications via email</div>
                </label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif"
                       checked="@PushNotifications"
                       @onchange="e => PushNotifications = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="pushNotif">
                    <strong>Push Notifications</strong>
                    <div class="text-muted small">Receive push notifications in browser</div>
                </label>
            </div>

            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="weeklyDigest"
                       checked="@WeeklyDigest"
                       @onchange="e => WeeklyDigest = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="weeklyDigest">
                    <strong>Weekly Digest</strong>
                    <div class="text-muted small">Get a weekly summary of activity</div>
                </label>
            </div>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-header"><strong>Muted Channels</strong></div>
        <div class="card-body">
            @foreach (var channel in AllChannels)
            {
                var isMuted = MutedChannels.Contains(channel);
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@isMuted"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>
    </div>

    @if (!string.IsNullOrEmpty(StatusMessage))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @StatusMessage
            <button type="button" class="btn-close" @onclick="() => StatusMessage = string.Empty"></button>
        </div>
    }

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
        @if (IsSaving)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
        }
        Save Preferences
    </button>
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = [];

    private static readonly string[] AllChannels = ["general", "announcements", "marketing", "engineering", "design"];

    private string StatusMessage { get; set; } = "";
    private bool IsSaving { get; set; }

    protected override void OnParametersSet()
    {
        EmailNotifications = Prefs.EmailNotifications;
        PushNotifications = Prefs.PushNotifications;
        WeeklyDigest = Prefs.WeeklyDigest;
        MutedChannels = [.. Prefs.MutedChannels];
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        StatusMessage = "";
        try
        {
            var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, [.. MutedChannels]);
            await OnSave.InvokeAsync(updated);
            StatusMessage = "Preferences saved successfully!";
        }
        finally
        {
            IsSaving = false;
        }
    }
}

