.settings-dashboard {
    max-width: 1100px;
    margin: 0 auto;
    padding: 1.5rem;
}

.settings-layout {
    display: flex;
    gap: 2rem;
    min-height: 600px;
}

.settings-sidebar-container {
    width: 220px;
    flex-shrink: 0;
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 0.5rem 0;
    border: 1px solid #dee2e6;
    align-self: flex-start;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

/* Sidebar nav */
::deep .settings-sidebar .settings-nav-btn {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    width: 100%;
    text-align: left;
    border: none;
    background: transparent;
    padding: 0.6rem 1rem;
    color: #495057;
    font-weight: 500;
    border-radius: 0;
    transition: background-color 0.15s, color 0.15s;
    cursor: pointer;
}

::deep .settings-sidebar .settings-nav-btn:hover {
    background-color: #e9ecef;
    color: #212529;
}

::deep .settings-sidebar .settings-nav-btn.active {
    background-color: #0d6efd;
    color: #fff;
}

::deep .settings-sidebar .sidebar-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

/* Appearance preview */
::deep .preview-dark {
    border: 1px solid #444;
}

::deep .preview-dark .badge.bg-primary {
    background-color: #4a9eff !important;
}

::deep .preview-light {
    border: 1px solid #dee2e6;
}

